class Summary(unittest.TestCase):
    def test_omitted_protocol_uses_current_protocol(self):
        self.assertEqual(
            run({"command": "summary", "receipts": []}),
            {"protocol": "2", "accepted_count": 0, "duplicate_count": 0},
